from itertools import permutations

def solve(facts):
    jobs = sorted(facts['jobs'], key=lambda j: j['id'])
    n = len(jobs)
    indexes = {j['id']: i for i, j in enumerate(jobs)}
    requirements = [sum(1 << k for k in set(indexes[p] for p in j['predecessors'])) for j in jobs]
    best = None
    best_starts = None

    def visit(mask, time, cost, order, starts):
        nonlocal best, best_starts
        if len(order) == n:
            candidate = (cost, time, order)
            if best is None or candidate < best:
                best = candidate
                best_starts = starts
            return
        for i, job in enumerate(jobs):
            bit = 1 << i
            if mask & bit or requirements[i] & mask != requirements[i]:
                continue
            start = max(time, job['release'])
            end = start + job['duration']
            visit(mask | bit, end,
                  cost + job['weight'] * max(0, end - job['due']),
                  order + (job['id'],), starts + (start,))

    visit(0, 0, 0, (), ())
    if best is None:
        raise ValueError('No feasible order')
    return {'order': list(best[2]), 'starts': list(best_starts),
            'finish': best[1], 'weighted_tardiness': best[0]}

def check(answer, facts):
    if not isinstance(answer, dict) or set(answer) != {'order', 'starts', 'finish', 'weighted_tardiness'}:
        return False
    jobs = facts['jobs']
    optimum = None
    optimum_starts = None
    for sequence in permutations(jobs):
        completed = {}
        time = 0
        penalty = 0
        starts = []
        valid = True
        for job in sequence:
            if any(p not in completed for p in job['predecessors']):
                valid = False
                break
            earliest = max([time, job['release']] + [completed[p] for p in job['predecessors']])
            starts.append(earliest)
            time = earliest + job['duration']
            completed[job['id']] = time
            if time > job['due']:
                penalty += job['weight'] * (time - job['due'])
        if valid:
            objective = (penalty, time, tuple(job['id'] for job in sequence))
            if optimum is None or objective < optimum:
                optimum = objective
                optimum_starts = starts
    if optimum is None:
        return False
    return answer == {'order': list(optimum[2]), 'starts': optimum_starts,
                      'finish': optimum[1], 'weighted_tardiness': optimum[0]}
